#!/usr/bin/env python3
"""Writes Parse/EnvProc.lean: the assembly of read_sbr_envelope's block obligations.

Usage: proc.py > Kraken/X64/Examples/Sbr/Parse/EnvProc.lean
PROVED: label -> (module, extra args) of the block theorems `blk_<label>`.
"""
import re, glob, os

LABS = ("read_sbr_envelope L57c1 L57c9 L57ef L5834 L584c L5893 L58a4 L58c5 L58e6 L58f1 L58fd "
        "L590d L5930 L5940 L595a L5998 L59d8 L5a0d L5a11 L5a38 L5a60 L5a95 L5ad0 L5ae4 L5b25 "
        "L5b61 L5b93 L5b97 L5bc7 L5be0 L5bf6 L5c26 L5c5e L5ca5 L5cd0 L5ced L5cfd L5d35 L5d75 "
        "L5da6 L5daa L5dd7 L5df4 L5e29 L5e2d L5e4b L5e70 L5e8d L5eca L5f07 L5f3a L5f3e L5f6e "
        "L5f90 L5fac L5fdd L5fe9 L6019 L603e L6044 L6048 L6063 L606a L6075 L60a6 done L60b8 "
        "L60bd L60c2 L60c7 L60cc L60d1 L60d6 L60db L60e0 L60e5 L60ea L60ef L60f4 L60f9").split()

full = lambda l: l if l == "read_sbr_envelope" else "read_sbr_envelope." + l
name = lambda l: "entry" if l == "read_sbr_envelope" else l

# Scan the block files for `theorem blk_<name> (k ...) ...` and their extra hypotheses.
here = os.path.dirname(os.path.abspath(__file__))
pdir = os.path.join(here, "../../../../Kraken/X64/Examples/Sbr/Parse")
proved, mods = {}, []
for f in sorted(glob.glob(os.path.join(pdir, "Env*.lean"))):
  mod = os.path.basename(f)[:-5]
  if mod in ("EnvProc",):
    continue
  txt = open(f).read()
  found = False
  for m in re.finditer(r"theorem blk_(\w+) \(k : Nat\)([^:]*?(?:\([^)]*\)\s*)*?)\(x : EArgs\)", txt):
    args = "k"
    seg = m.group(2)
    if "(hk" in seg: args += " hk"
    args += " Ext"
    if "(hAv" in seg: args += " hAv"
    proved[m.group(1)] = args
    found = True
  if found:
    mods.append(mod)

open_ = [l for l in LABS if name(l) not in proved]
imports = "\n".join(f"import Kraken.X64.Examples.Sbr.Parse.{m}" for m in mods + ["EnvStack"])
lst = ",\n  ".join(f'"{full(l)}"' for l in open_) if open_ else ""
cases = []
for l in LABS:
  if name(l) in proved:
    cases.append(f"    · exact blk_{name(l)} {proved[name(l)]} x ra t₀ blk hblk")
  else:
    cases.append("    · exact hopen x ra t₀ _ (by decide) blk hblk")
pat = " | ".join(["rfl"] * len(LABS))
labs_txt = ",\n  ".join(f'"{full(l)}"' for l in LABS)
print(f'''{imports}

/-!
# `read_sbr_envelope`: the procedure

Generated by `scripts/sbr/parse/env/proc.py`. `read_sbr_envelope_spec`: the contract
(`EnvPre`/`EnvPost`, `EnvSpec.lean`) from the block obligations, by `ProcSpec.of_cfg_post`. The
block obligations not proved in the `Env*` files are the hypothesis `hopen` (the labels
`openLabels`, {len(open_)} of {len(LABS)}).
-/

open Kraken Kraken.SysV Mem Kraken.X64.Parser Std.WP MachineWP
open Kraken.Examples.Sbr Kraken.Examples.Sbr.Apply Kraken.Examples.Sbr.Vlc

set_option mvcgen.warning false
set_option grind.warning false

namespace Kraken.Examples.Sbr.Env

/-- The block obligations not proved here. -/
def openLabels : List Label := [
  {lst}]

theorem labels_body : Program.labels body = [
  {labs_txt}] := by decide

theorem body_wf : Program.WF body := by decide

variable [CodeEnv]

/-- `read_sbr_envelope`'s contract at `k` bytes of callee stack. -/
abbrev EnvSpecP (k : Nat) (Ext : Mem 64 → Prop) : Prop :=
  cenv.ProcSpec ((_root_.Executable.labels cenv).label "read_sbr_envelope") (EnvPre k Ext)
    (EnvPost k Ext)

theorem read_sbr_envelope_spec (hpl : Program.PlacedIn body) (k : Nat) (hk : k ≤ 2 ^ 32)
    (Ext : Mem 64 → Prop) (hAv : AvLogSpec Ext k)
    (hopen : ∀ x ra t₀ l, l ∈ openLabels → BlockOb k Ext x ra t₀ l) : EnvSpecP k Ext := by
  refine Kraken.Executable.ProcSpec.of_cfg_post (p := body) (table k Ext) (Post' k Ext) var
    (hblocks := ?_) (hpre := ?_) (hpost := ?_) (hwf := body_wf)
  · intro x ra t₀ l blk hblk
    have hl := Program.blockAt_mem_labels hblk
    rw [labels_body] at hl
    simp only [List.mem_cons, List.not_mem_nil, or_false] at hl
    rcases hl with {pat}
{chr(10).join(cases)}
  · rintro x ra t ⟨hcall, hc⟩
    exact ⟨rfl, hc, hcall⟩
  · exact post_of k hk Ext

end Kraken.Examples.Sbr.Env''')
